'use client';

import { useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import { usePointerDrag } from './use-pointer-drag';
import './resizable-split-pane.css';

export interface ResizableSplitPaneProps {
  start: ReactNode;
  end: ReactNode;
  /** Width of the first pane, in percent. */
  value: number;
  onChange: (value: number) => void;
  min?: number;
  max?: number;
  /** Accessible name for the separator. */
  label: string;
  className?: string;
}

/**
 * Two panes and a draggable separator. The separator is focusable: arrow
 * keys move it 5% (Shift for 10%), Home and End jump to the limits, and its
 * current position is exposed as a value.
 */
export function ResizableSplitPane({
  start,
  end,
  value,
  onChange,
  min = 20,
  max = 80,
  label,
  className = '',
}: ResizableSplitPaneProps) {
  const root = useRef<HTMLDivElement>(null);
  const [dragging, setDragging] = useState(false);
  const origin = useRef(value);
  const clamp = (v: number) => Math.round(Math.max(min, Math.min(max, v)));

  const drag = usePointerDrag({
    onStart: () => {
      origin.current = value;
      setDragging(true);
    },
    onMove: ({ dx }) => {
      const width = root.current?.clientWidth ?? 1;
      onChange(clamp(origin.current + (dx / width) * 100));
    },
    onEnd: () => setDragging(false),
  });

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.shiftKey ? 10 : 5;
    const next: Record<string, number> = {
      ArrowLeft: value - step,
      ArrowDown: value - step,
      ArrowRight: value + step,
      ArrowUp: value + step,
      Home: min,
      End: max,
    };
    if (event.key in next) {
      event.preventDefault();
      onChange(clamp(next[event.key]));
    }
  };

  return (
    <div
      ref={root}
      className={`mg-split-pane ${className}`}
      data-dragging={dragging}
      style={{ gridTemplateColumns: `${value}fr 12px ${100 - value}fr` }}
    >
      <div className='mg-split-pane__pane'>{start}</div>
      <div
        role='separator'
        tabIndex={0}
        aria-orientation='vertical'
        aria-label={label}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={value}
        aria-valuetext={`${value}% and ${100 - value}%`}
        className='mg-split-pane__handle'
        onKeyDown={onKeyDown}
        {...drag}
      >
        <span aria-hidden='true' />
      </div>
      <div className='mg-split-pane__pane'>{end}</div>
    </div>
  );
}

.mg-split-pane {
  display: grid;
  min-height: 150px;
  overflow: hidden;
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 12px;
  background: #fff;
  color: var(--mg-ink, #0c1738);
  transition: grid-template-columns 160ms ease-out;
}

.mg-split-pane[data-dragging='true'] {
  transition: none;
  user-select: none;
  -webkit-user-select: none;
}

.mg-split-pane__pane {
  min-width: 0;
  overflow: hidden;
  padding: 12px;
}

.mg-split-pane__handle {
  position: relative;
  display: grid;
  place-items: center;
  background: var(--mg-foam, #f5f8ff);
  cursor: col-resize;
  touch-action: none;
}

/* A wider invisible hit area than the 12px you see. */
.mg-split-pane__handle::before {
  position: absolute;
  inset: 0 -10px;
  content: '';
}

.mg-split-pane__handle span {
  width: 4px;
  height: 36px;
  border-radius: 2px;
  background: #8a96bd;
  transition: background-color 160ms ease;
}

.mg-split-pane__handle:hover span,
.mg-split-pane[data-dragging='true'] .mg-split-pane__handle span {
  background: var(--mg-accent, #164cff);
}

.mg-split-pane__handle:focus-visible {
  outline: 3px solid var(--mg-accent, #164cff);
  outline-offset: -3px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-split-pane,
  .mg-split-pane__handle span {
    transition: none;
  }
}

'use client';

import { useRef, type PointerEvent as ReactPointerEvent } from 'react';

export interface DragState {
  /** Distance from where the drag started, in pixels. */
  dx: number;
  dy: number;
  /** Pointer position in viewport coordinates. */
  clientX: number;
  clientY: number;
  /** Smoothed velocity in pixels per millisecond. */
  vx: number;
  vy: number;
}

export interface PointerDragOptions {
  /** Return false to ignore this press. */
  onStart?: (event: ReactPointerEvent<HTMLElement>) => boolean | void;
  onMove?: (drag: DragState) => void;
  /**
   * `cancelled` is true when the browser took the gesture over, for example
   * to scroll the page on touch.
   */
  onEnd?: (drag: DragState, cancelled: boolean) => void;
}

interface Active {
  id: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  lastTime: number;
  vx: number;
  vy: number;
}

/**
 * Pointer-capture dragging for mouse, pen and touch. Spread the returned
 * handlers on the element that starts the drag. Pair it with a CSS
 * `touch-action` that leaves the scroll axis you still want to the browser.
 */
export function usePointerDrag(options: PointerDragOptions) {
  const latest = useRef(options);
  latest.current = options;
  const active = useRef<Active | null>(null);

  const snapshot = (a: Active, x: number, y: number): DragState => ({
    dx: x - a.startX,
    dy: y - a.startY,
    clientX: x,
    clientY: y,
    vx: a.vx,
    vy: a.vy,
  });

  const finish = (
    event: ReactPointerEvent<HTMLElement>,
    cancelled: boolean
  ) => {
    const a = active.current;
    if (!a || a.id !== event.pointerId) return;
    active.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    // A pause before release means the pointer was not really flung.
    if (event.timeStamp - a.lastTime > 80) {
      a.vx = 0;
      a.vy = 0;
    }
    latest.current.onEnd?.(
      snapshot(a, event.clientX, event.clientY),
      cancelled
    );
  };

  return {
    onPointerDown(event: ReactPointerEvent<HTMLElement>) {
      if (event.button !== 0 || active.current) return;
      if (latest.current.onStart?.(event) === false) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      active.current = {
        id: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastTime: event.timeStamp,
        vx: 0,
        vy: 0,
      };
    },
    onPointerMove(event: ReactPointerEvent<HTMLElement>) {
      const a = active.current;
      if (!a || a.id !== event.pointerId) return;
      const dt = Math.max(1, event.timeStamp - a.lastTime);
      a.vx = a.vx * 0.6 + ((event.clientX - a.lastX) / dt) * 0.4;
      a.vy = a.vy * 0.6 + ((event.clientY - a.lastY) / dt) * 0.4;
      a.lastX = event.clientX;
      a.lastY = event.clientY;
      a.lastTime = event.timeStamp;
      latest.current.onMove?.(snapshot(a, event.clientX, event.clientY));
    },
    onPointerUp(event: ReactPointerEvent<HTMLElement>) {
      finish(event, false);
    },
    onPointerCancel(event: ReactPointerEvent<HTMLElement>) {
      finish(event, true);
    },
  };
}
